import { neon } from "@neondatabase/serverless";
import { drizzle } from "drizzle-orm/neon-http";

import { env } from "@/lib/env";
import * as schema from "@/drizzle/schema";

// The Neon HTTP driver is the right pick for App Router server components:
// short-lived requests, no persistent connections, no pooler exhaustion.
// The schema is generated by `pnpm db:introspect` from the SQL migrations.
const sql = neon(env.DATABASE_URL);
export const db = drizzle(sql, { schema });
